def split_csv(line):
    fields = []
    i = 0

    while i <= len(line):
        if i == len(line):
            # End of line - add the last field and break
            fields.append('')
            break

        if line[i] == '"':
            # Quoted field
            i += 1
            field = []
            while i < len(line):
                if line[i] == '"':
                    if i + 1 < len(line) and line[i + 1] == '"':
                        # Doubled quote - represents one quote
                        field.append('"')
                        i += 2
                    else:
                        # End of quoted field
                        i += 1
                        # Check what follows
                        if i == len(line):
                            # End of line - valid
                            fields.append(''.join(field))
                            break
                        elif line[i] == ',':
                            # Comma follows - valid
                            fields.append(''.join(field))
                            i += 1
                            break
                        else:
                            # Invalid character after closing quote
                            return None
                else:
                    field.append(line[i])
                    i += 1
            else:
                # Reached end of line without closing quote
                return None
        elif line[i] == ',':
            # Empty field before comma
            fields.append('')
            i += 1
        else:
            # Unquoted field
            field = []
            while i < len(line) and line[i] != ',':
                if line[i] == '"':
                    # Double quote in unquoted field - malformed
                    return None
                field.append(line[i])
                i += 1
            fields.append(''.join(field))
            if i < len(line) and line[i] == ',':
                i += 1

    return fields

